/* From Uiverse.io by fbernack  - Tags: input */
.__UIV_SCOPE__ .mat-input {
  position: relative;
  font-size: inherit;
}

.__UIV_SCOPE__ .mat-input input {
  border-width: 0 0 1px;
  outline: none;
  background-color: #0000000a;
  border-radius: 4px 4px 0 0;
  padding: 1.8em 0.75em 0.75em;
  border-color: #8c8c8c;
  border-style: solid;
  font-size: inherit;
  transition: 0.1s;
}

.__UIV_SCOPE__ .mat-input input:hover,
.__UIV_SCOPE__ .mat-input input:focus {
  border-bottom-width: 2px;
  padding-bottom: calc(0.75em - 1px);
}

.__UIV_SCOPE__ .mat-input input:hover {
  border-color: #121212;
}

.__UIV_SCOPE__ .mat-input input:focus {
  border-color: #2196f3;
}

.__UIV_SCOPE__ .mat-input label {
  position: absolute;
  top: 1.4em;
  left: 1em;
  pointer-events: none;
  transition: 0.2s;
  color: #0009;
}

.__UIV_SCOPE__ .mat-input:has(input:focus) label {
  color: #2196f3;
}

.__UIV_SCOPE__ .mat-input:has(input:focus) label,
.__UIV_SCOPE__ .mat-input:not(:has(input:placeholder-shown)) label {
  top: 0.75em;
  font-size: 0.8em;
}

.__UIV_SCOPE__ .mat-input input::placeholder {
  opacity: 0;
  transition: 0.2s;
  color: #aaa;
}

.__UIV_SCOPE__ .mat-input input:focus::placeholder {
  opacity: 1;
}
